import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Tabs } from "@/registry/erbium/ui/tabs";

import PlaygroundExample, { defaultProps as PlaygroundDefaults } from "./variants/playground";



import OverviewExample from "./variants/overview";



import SelectionExample from "./variants/selection";



import VerticalExample from "./variants/vertical";



import DisabledExample from "./variants/disabled";



import IconsExample from "./variants/icons";



const meta = {
  component: Tabs,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Display one tab panel at a time, switching between related sections of content.

**Import:** `@/registry/erbium/ui/tabs`

## Usage

```tsx
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/registry/erbium/ui/tabs";
```

```tsx
<Tabs defaultValue="account" className="w-[400px]">
  <TabsList>
    <TabsTrigger value="account">Account</TabsTrigger>
    <TabsTrigger value="password">Password</TabsTrigger>
  </TabsList>
  <TabsContent value="account">Make changes to your account here.</TabsContent>
  <TabsContent value="password">Change your password here.</TabsContent>
</Tabs>
```

## Composition

Use the following composition to build `Tabs`:

```text
Tabs
├── TabsList
│   ├── TabsTrigger
│   └── TabsTrigger
├── TabsContent
└── TabsContent
```

## External documentation

Explore the underlying Base UI tabs API and Motion for React, used for the animated indicator.

- [Tabs](https://base-ui.com/react/components/tabs)
- [Motion for React](https://motion.dev/docs/react)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Tabs>;

export default { ...meta, title: "Components/Tabs",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof Tabs> = {
  argTypes: {
    defaultValue: { control: "select", options: ["one", "two"] },
    orientation: { control: "select", options: ["horizontal", "vertical"] },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/registry/erbium/ui/tabs";
import type * as React from "react";

export const defaultProps = {
  defaultValue: "one",
  orientation: "horizontal",
} satisfies React.ComponentProps<typeof Tabs>;

export default function TabsPlaygroundExample(
  args: React.ComponentProps<typeof Tabs> = defaultProps,
) {
  return (
    <Tabs {...args} className="w-72">
      <TabsList>
        <TabsTrigger value="one">First</TabsTrigger>
        <TabsTrigger value="two">Second</TabsTrigger>
      </TabsList>
      <TabsContent value="one">First panel</TabsContent>
      <TabsContent value="two">Second panel</TabsContent>
    </Tabs>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { Button } from "@/registry/erbium/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/registry/erbium/ui/card";
import { Input } from "@/registry/erbium/ui/input";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { PasswordInput } from "@/registry/erbium/ui/password-input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/registry/erbium/ui/tabs";

export default function TabsExample() {
  return (
    <div className="flex w-full max-w-sm flex-col gap-section">
      <Tabs defaultValue="account">
        <TabsList>
          <TabsTrigger value="account">Account</TabsTrigger>
          <TabsTrigger value="password">Password</TabsTrigger>
        </TabsList>
        <TabsContent value="account">
          <Card>
            <CardHeader>
              <CardTitle>Account</CardTitle>
              <CardDescription>
                Make changes to your account here. Click save when you&apos;re done.
              </CardDescription>
            </CardHeader>
            <CardContent className="grid gap-section">
              <Field>
                <FieldLabel>Name</FieldLabel>
                <Input defaultValue="Pedro Duarte" />
              </Field>
              <Field>
                <FieldLabel>Username</FieldLabel>
                <Input defaultValue="@peduarte" />
              </Field>
            </CardContent>
            <CardFooter>
              <Button>Save changes</Button>
            </CardFooter>
          </Card>
        </TabsContent>
        <TabsContent value="password">
          <Card>
            <CardHeader>
              <CardTitle>Password</CardTitle>
              <CardDescription>
                Change your password here. After saving, you&apos;ll be logged out.
              </CardDescription>
            </CardHeader>
            <CardContent className="grid gap-section">
              <Field>
                <FieldLabel>Current password</FieldLabel>
                <PasswordInput />
              </Field>
              <Field>
                <FieldLabel>New password</FieldLabel>
                <PasswordInput autoComplete="new-password" />
              </Field>
            </CardContent>
            <CardFooter>
              <Button>Save password</Button>
            </CardFooter>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}
" },
    },
  },
  render: OverviewExample,
};

